package com.dpworld.fms.routing;
import com.dpworld.fms.domain.GeoPoint;import java.util.*;import org.locationtech.jts.geom.*;import org.locationtech.jts.index.strtree.STRtree;import org.locationtech.jts.operation.distance.DistanceOp;
public final class GpsMapMatcher {
 private final Map<String,MapNode>nodes;private final STRtree index=new STRtree();private final GeometryFactory geometry=new GeometryFactory(new PrecisionModel(),4326);private final double maxDistanceMetres;
 public GpsMapMatcher(Collection<MapNode>nodes,Collection<RoadSegment>segments,double maxDistanceMetres){this.nodes=new HashMap<>();nodes.forEach(n->this.nodes.put(n.id(),n));this.maxDistanceMetres=maxDistanceMetres;segments.forEach(s->{MapNode from=this.nodes.get(s.from()),to=this.nodes.get(s.to());if(from!=null&&to!=null){LineString line=geometry.createLineString(new Coordinate[]{coordinate(from.point()),coordinate(to.point())});index.insert(line.getEnvelopeInternal(),new IndexedSegment(s,line));}});index.build();}
 public Match match(GeoPoint position,double headingDegrees,String previousSegmentId){double degrees=maxDistanceMetres/111_320d;Envelope search=new Envelope(position.longitude()-degrees,position.longitude()+degrees,position.latitude()-degrees,position.latitude()+degrees);Point point=geometry.createPoint(coordinate(position));Match best=null;for(Object value:index.query(search)){IndexedSegment candidate=(IndexedSegment)value;Coordinate nearest=DistanceOp.nearestPoints(candidate.geometry,point)[0];GeoPoint snapped=new GeoPoint(nearest.y,nearest.x);double distance=position.distanceMetres(snapped);if(distance>maxDistanceMetres)continue;double direction=bearing(nodes.get(candidate.segment.from()).point(),nodes.get(candidate.segment.to()).point());double headingDelta=angleDelta(headingDegrees,direction);double continuity=Objects.equals(previousSegmentId,candidate.segment.id())?0:10;double score=distance+headingDelta/18d+continuity;if(best==null||score<best.score())best=new Match(candidate.segment.id(),nearestNode(candidate.segment,snapped),snapped,distance,headingDelta,score,Math.max(0,1-score/(maxDistanceMetres+20)));}return best;}
 private String nearestNode(RoadSegment s,GeoPoint p){MapNode from=nodes.get(s.from()),to=nodes.get(s.to());return p.distanceMetres(from.point())<=p.distanceMetres(to.point())?from.id():to.id();}private Coordinate coordinate(GeoPoint p){return new Coordinate(p.longitude(),p.latitude());}private static double bearing(GeoPoint a,GeoPoint b){double y=Math.sin(Math.toRadians(b.longitude()-a.longitude()))*Math.cos(Math.toRadians(b.latitude()));double x=Math.cos(Math.toRadians(a.latitude()))*Math.sin(Math.toRadians(b.latitude()))-Math.sin(Math.toRadians(a.latitude()))*Math.cos(Math.toRadians(b.latitude()))*Math.cos(Math.toRadians(b.longitude()-a.longitude()));return(Math.toDegrees(Math.atan2(y,x))+360)%360;}private static double angleDelta(double a,double b){double d=Math.abs(a-b)%360;return d>180?360-d:d;}private record IndexedSegment(RoadSegment segment,LineString geometry){}public record Match(String segmentId,String nodeId,GeoPoint snappedPosition,double distanceMetres,double headingDelta,double score,double confidence){}
}
